BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Form of written representations
(1, 'Written Representations', 'Under AU-C 580, what is the required form for management''s written representations to the auditor?', '["A written letter addressed to the auditor", "An oral statement recorded in the audit workpapers", "An email from any member of the accounting staff", "A signed affidavit notarized by a third party"]'::jsonb, 0, 'AU-C 580.15 requires that written representations be in the form of a representation letter addressed to the auditor. Oral statements, even if documented in workpapers, do not satisfy this requirement because they lack the formality and accountability of a written document. Unlike an email or notarized affidavit (choices C and D), the standard specifically prescribes a formal written letter as the required form.', 'easy', 1),

-- Q2: medium / L2 — Uncorrected misstatements representation
(1, 'Written Representations', 'During the audit of Bellwood Industries for the year ended December 31, 2025, the engagement team at Stratton & Reeves identifies $45,000 of uncorrected misstatements that management considers immaterial. When preparing the representation letter, AU-C 580 requires management to represent regarding these misstatements that:', '["The misstatements have been corrected in a subsequent period", "Management believes the effects of the uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole", "Management was unaware of the misstatements until the auditor identified them", "The uncorrected misstatements do not require footnote disclosure"]'::jsonb, 1, 'AU-C 580.11 requires management to represent that it believes the effects of uncorrected misstatements are immaterial, both individually and in the aggregate, to the financial statements as a whole. This is not about correcting them later (choice A) or claiming ignorance (choice C). The representation focuses on management''s materiality assessment of the accumulated misstatements identified during the audit.', 'medium', 2),

-- Q3: medium / L2 — Completeness of information provided
(1, 'Written Representations', 'The audit team at Markham & Associates completes fieldwork for Ridgepoint Corp.''s December 31, 2025 audit. The engagement partner includes a completeness representation in the management representation letter. Under AU-C 580, this representation requires management to confirm that it has provided the auditor with:', '["Only the information specifically requested in writing during fieldwork", "Copies of all source documents supporting every recorded transaction", "Access to all information of which management is aware that is relevant to the preparation and fair presentation of the financial statements", "A complete list of every transaction that occurred during the fiscal year"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that it has provided the auditor with all information relevant to the financial statements of which management is aware. This is broader than only items specifically requested in writing (choice A) but does not extend to every source document or every transaction regardless of materiality. The representation centers on relevance and management''s actual knowledge.', 'medium', 2),

-- Q4: hard / L4 — Effect of omitting a required representation on the opinion
(1, 'Written Representations', 'During the audit of Westbrook Financial for December 31, 2025, the engagement partner at Carroll & Finch obtains a management representation letter that omits the required representation about completeness of information. Management''s CEO provides oral assurance that all information was shared but refuses to include it in writing. Under AU-C 580, the auditor should:', '["Accept the oral assurance as a reasonable substitute and issue an unmodified opinion", "Issue a qualified opinion for the scope limitation caused by the omission", "Withdraw from the engagement since an incomplete letter invalidates all other representations", "Disclaim an opinion because management has not provided a required written representation"]'::jsonb, 3, 'AU-C 580.20 states that if management does not provide one or more of the requested written representations, the auditor shall disclaim an opinion on the financial statements. An oral statement cannot substitute for a required written representation. A qualified opinion (choice B) is insufficient because the refusal to provide a required representation prevents the auditor from obtaining sufficient appropriate audit evidence.', 'hard', 4),

-- Q5: medium / L3 — Going concern representation applied in scenario
(1, 'Written Representations', 'Palmer Industries reports declining revenue for the third consecutive year, and its December 31, 2025 financial statements include a going concern disclosure. The engagement team at Lawson & Beck prepares the representation letter. Under AU-C 580, what representation should the auditor request from management regarding going concern?', '["That management''s plans to mitigate substantial doubt are disclosed in the financial statements, including the significant assumptions underlying those plans", "That the auditor will not be held liable if the entity ceases operations within twelve months", "That the entity will continue as a going concern for at least twenty-four months following year-end", "That the going concern disclosure was added solely at the auditor''s request"]'::jsonb, 0, 'AU-C 580.A12 indicates the auditor should obtain representations about management''s plans to mitigate going concern doubt and the adequacy of related financial statement disclosures, including significant assumptions. Choice C incorrectly requires a guarantee of continued operations, which management cannot reasonably provide. The representation addresses the completeness and adequacy of disclosures, not liability shifting or guarantees.', 'medium', 3),

-- Q6: medium / L2 — All transactions recorded representation
(1, 'Written Representations', 'During the audit of Crestfield Manufacturing for December 31, 2025, the controller asks the engagement partner at Quinn & Blake why the representation letter includes a statement about recording all transactions. Under AU-C 580, this representation confirms that:', '["The entity''s accounting system is free from all material processing errors", "The auditor bears responsibility for identifying any unrecorded transactions", "The financial statements were prepared using a cash basis of accounting", "All transactions have been recorded and are reflected in the financial statements"]'::jsonb, 3, 'AU-C 580.11 requires management to represent that all transactions have been recorded and reflected in the financial statements, directly supporting the completeness assertion at the financial statement level. Choice A overstates the claim because the representation addresses completeness of recording, not an assertion that the system is error-free. This representation supplements the auditor''s own independent testing of completeness.', 'medium', 2),

-- Q7: medium / L3 — Corroborative role of written representations
(1, 'Written Representations', 'A staff auditor at Henderson & Park questions whether obtaining a signed management representation letter for Oakdale Corp.''s December 31, 2025 audit can reduce the extent of substantive testing of inventory. The engagement partner explains the evidentiary role of written representations. Under AU-C 580, written representations:', '["Replace substantive testing when management is considered highly reliable and cooperative", "Are corroborative evidence that do not reduce the need for other audit procedures the auditor considers necessary", "Eliminate the need for external confirmations in areas covered by the letter", "Serve as the primary source of audit evidence when other procedures are impractical"]'::jsonb, 1, 'AU-C 580.04 clarifies that written representations are necessary audit evidence but do not substitute for other procedures the auditor considers necessary. They serve a corroborative role alongside other evidence rather than replacing it. Choice A incorrectly suggests that management reliability can reduce substantive procedures. The auditor must still perform all planned procedures regardless of the representations obtained.', 'medium', 3),

-- Q8: medium / L2 — Access to records and personnel
(1, 'Written Representations', 'The engagement team at Griffin & Hale begins the audit of Sunridge Technology for December 31, 2025 and identifies critical records needed for testing. Under AU-C 580, the management representation letter requires management to confirm that it has provided the auditor with:', '["Electronic copies of all records in the auditor''s preferred file format", "Only records that management independently considers relevant to the engagement", "Access to all information that management is aware is relevant, including records, documentation, and personnel as agreed in the engagement terms", "Physical access to the entity''s data centers and all server hardware"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that it has provided access to all information relevant to the financial statements, including records, documentation, and other matters as agreed in the engagement letter under AU-C 210. Choice B is too narrow because it limits relevance to management''s sole judgment, whereas the standard requires disclosure of all relevant information of which management is aware.', 'medium', 2),

-- Q9: easy / L1 — Period covered by the representation letter
(1, 'Written Representations', 'Under AU-C 580, what period do management''s written representations cover in an audit engagement?', '["All periods referred to in the auditor''s report", "Only the most recent fiscal year under audit", "The twelve months before the date of the auditor''s report", "The period from engagement acceptance through fieldwork completion"]'::jsonb, 0, 'AU-C 580.14 requires that written representations cover all periods referred to in the auditor''s report. For comparative financial statements covering two years, the representation letter must address both years presented. Choice B is incorrect because representations are not limited to the most recent year alone. The standard ties the coverage period directly to the scope of the auditor''s report.', 'easy', 1),

-- Q10: hard / L4 — Group audit component representations
(1, 'Written Representations', 'Sterling Global Corp. has three wholly owned subsidiaries, each audited by separate component auditors. The group engagement partner at Caldwell & Morse completes the December 31, 2025 group audit and determines what written representations to obtain regarding component financial information. Under AU-C 600, the group engagement partner should:', '["Rely exclusively on each component auditor''s separately obtained representation letter from component management", "Obtain component management representations only for subsidiaries exceeding 25% of consolidated assets", "Accept oral confirmations from component management relayed through the component auditors", "Obtain written representations from group management covering matters relevant to the group financial statements, including the completeness of component information"]'::jsonb, 3, 'AU-C 600.41 requires the group engagement partner to obtain written representations from group management about matters relevant to the consolidated financial statements, including the completeness of information regarding components. The partner cannot rely solely on component-level letters (choice A) because group management bears overall responsibility for the group financial statements and their completeness.', 'hard', 4),

-- Q11: medium / L2 — Litigation and claims representation
(1, 'Written Representations', 'During the audit of Greystone Holdings for December 31, 2025, the engagement team at Wallace & Price prepares the management representation letter addressing pending litigation. Under AU-C 580, management should represent that:', '["Legal counsel has confirmed there is no material litigation exposure for the entity", "Management is unaware of any lawsuits regardless of their potential financial impact", "All known actual or possible litigation and claims whose effects should be considered in preparing the financial statements have been disclosed to the auditor", "The entity carries sufficient insurance to fully cover all potential litigation losses"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that all known actual or possible litigation and claims whose effects should be considered when preparing the financial statements have been disclosed. This extends beyond confirmed cases to include possible claims. Choice A is too narrow because it relies on counsel''s confirmation rather than management''s own comprehensive disclosure obligation under the standard.', 'medium', 2),

-- Q12: easy / L1 — Required versus additional representations
(1, 'Written Representations', 'Under AU-C 580, what is the distinction between required and additional written representations?', '["Required representations are optional for low-risk engagements while additional ones are always mandatory", "Required representations are specified by AU-C 580 for every audit while additional representations address entity-specific matters", "Required representations cover financial data only while additional representations cover legal compliance matters", "Required representations are obtained verbally while additional representations must be in writing"]'::jsonb, 1, 'AU-C 580 distinguishes between representations required for all audits (such as completeness, fraud acknowledgment, and management responsibility) and additional representations the auditor may request based on entity-specific circumstances. Choice A reverses the mandatory nature because required representations are never optional. Both types appear in the same written letter, making choice D incorrect.', 'easy', 1),

-- Q13: easy / L1 — Management responsibility representation
(1, 'Written Representations', 'Under AU-C 580, what does the management responsibility representation in the representation letter confirm?', '["That the auditor has performed all procedures necessary to support the opinion", "That the auditor independently verified every material account balance", "That audit liability transfers from the auditor to management upon signing the letter", "That management acknowledges its responsibility for the preparation and fair presentation of the financial statements"]'::jsonb, 3, 'AU-C 580.10 requires management to acknowledge its responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework. This foundational representation aligns with the engagement terms established under AU-C 210. Choice C mischaracterizes the purpose because the representation confirms responsibility allocation rather than transferring audit liability.', 'easy', 1),

-- Q14: hard / L4 — Prior period representations in initial audit
(1, 'Written Representations', 'The audit firm Hawthorne & Reid accepts its first engagement to audit Ironclad Solutions for the year ended December 31, 2025, with comparative December 31, 2024 financial statements. The prior year was audited by a predecessor firm. The engagement partner must determine what written representations to obtain for the prior period. Under AU-C 580, the auditor should:', '["Obtain written representations from current management covering all periods referred to in the auditor''s report, including the prior year", "Request representations covering only the current year since the prior year was another firm''s responsibility", "Rely on the predecessor auditor''s representation letter from the prior year without seeking new representations", "Accept oral representations from the predecessor auditor regarding the prior year account balances"]'::jsonb, 0, 'AU-C 580.14 requires that written representations address all periods referred to in the auditor''s report. In an initial audit presenting comparative statements, the successor auditor must obtain representations from current management for both years. Choice B incorrectly limits the scope. The predecessor''s prior letter (choice C) does not satisfy the successor auditor''s requirement because current management retains ongoing responsibility for the financial statements.', 'hard', 4),

-- Q15: medium / L2 — Compliance with laws and regulations representation
(1, 'Written Representations', 'The engagement team at Doyle & Spencer completes the audit of Meridian Healthcare for December 31, 2025 and prepares the management representation letter. Under AU-C 580, management should represent regarding legal compliance that:', '["The entity has complied with every applicable federal and state regulation during the audit period", "All instances of identified or suspected noncompliance with laws and regulations whose effects should be considered in preparing the financial statements have been disclosed to the auditor", "Legal counsel has issued an unqualified opinion on the entity''s overall regulatory compliance", "No regulatory investigation of the entity has occurred during the current or prior fiscal year"]'::jsonb, 1, 'AU-C 580.11 requires management to represent that all identified or suspected noncompliance with laws and regulations whose effects should be considered in preparing the financial statements has been disclosed. Choice A overstates the representation because management cannot reasonably guarantee total compliance with every law. The representation focuses on disclosure of known or suspected noncompliance relevant to the financial statements.', 'medium', 2),

-- Q16: hard / L4 — Evaluating accounting estimate representations versus contradictory evidence
(1, 'Written Representations', 'During the audit of Pinnacle Resources for December 31, 2025, management''s allowance for doubtful accounts uses an expected credit loss model with a 2.5% default rate. The representation letter asserts the assumptions are reasonable. However, industry data and the entity''s own historical experience indicate a 5.0% rate is more appropriate. The engagement team at Keating & Howell should:', '["Accept the representation because the signed letter provides sufficient evidence for the estimate", "Issue an immediate disclaimer of opinion because management provided a misleading representation", "Evaluate whether the difference indicates management bias and consider the implications for the estimate and the audit report", "Disregard the representation letter entirely and independently recalculate the entire allowance"]'::jsonb, 2, 'AU-C 540.18 requires the auditor to evaluate whether management''s assumptions are reasonable, including assessing indicators of possible management bias. When assumptions materially diverge from industry benchmarks and historical data, the auditor must investigate rather than accept the representation at face value (choice A). Written representations about estimates do not override the auditor''s independent evaluation of methods, data, and assumptions.', 'hard', 4),

-- Q17: easy / L1 — Addressee of the management representation letter
(1, 'Written Representations', 'Under AU-C 580, to whom should the management representation letter be addressed?', '["The entity''s board of directors or audit committee", "The auditor or the audit firm", "The applicable securities regulatory authority", "The entity''s external legal counsel"]'::jsonb, 1, 'AU-C 580.15 states that the management representation letter should be addressed to the auditor. Since the auditor is the party relying on these representations to form an opinion on the financial statements, the letter is directed to the engagement partner or the audit firm. Choice A is incorrect because the letter flows from management to the auditor, not to the governance body.', 'easy', 1),

-- Q18: easy / L1 — Fraud knowledge representation specifics
(1, 'Written Representations', 'Under AU-C 580, what must management represent regarding its knowledge of fraud?', '["That management has designed controls that eliminate all fraud risk at the entity", "That no fraud of any kind occurred at the entity during the audit period", "That every employee with access to financial systems has been investigated for fraud", "Its knowledge of fraud or suspected fraud affecting the entity involving management, employees with significant internal control roles, or others where fraud could materially affect the financial statements"]'::jsonb, 3, 'AU-C 580.11 requires management to represent its knowledge of fraud or suspected fraud involving management, employees who have significant roles in internal control, or others where the fraud could have a material effect on the financial statements. Choice B overstates the claim because the representation concerns management''s knowledge of fraud, not a guarantee that no fraud occurred anywhere in the entity.', 'easy', 1),

-- Q19: easy / L2 — Internal control deficiencies disclosure representation
(1, 'Written Representations', 'During the audit of Harborview Inc. for December 31, 2025, the engagement partner at Fletcher & Dunn identifies several internal control deficiencies and drafts the representation letter. Under AU-C 580, management should represent that:', '["All significant deficiencies have been fully remediated before the letter date", "The entity''s internal control system is effective in all material respects", "It has disclosed to the auditor all deficiencies in internal control of which management is aware", "All control deficiencies are solely attributable to temporary staffing shortages"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that it has disclosed to the auditor all deficiencies in internal control of which management is aware. This representation does not require that deficiencies have been remediated (choice A) or that controls be effective (choice B). It ensures the auditor has received complete information about all known control weaknesses so they can be evaluated properly.', 'easy', 2),

-- Q20: medium / L3 — Intent and ability representation for held-to-maturity classification
(1, 'Written Representations', 'Oakwood Financial classifies $8 million of corporate bonds as held-to-maturity in its December 31, 2025 financial statements. The engagement team at Pryor & Simmons notes that this classification depends on management''s intent and financial ability. Under AU-C 580, the auditor should obtain a representation from management that:', '["Management has both the positive intent and the financial ability to hold the bonds to maturity", "The bonds'' current fair value exceeds their amortized cost basis at year-end", "Management is actively exploring early sale opportunities for the bond portfolio", "The bonds will be reclassified to trading securities if market interest rates decline significantly"]'::jsonb, 0, 'AU-C 580.A13 supports requesting representations about management''s intent and ability when they affect financial statement classification or measurement. Held-to-maturity classification under ASC 320 requires both positive intent and financial ability to hold to maturity. Choice B addresses valuation rather than classification intent. Without this representation, the auditor lacks corroboration for the HTM classification basis.', 'medium', 3),

-- Q21: medium / L2 — Subsequent events representation in the letter
(1, 'Written Representations', 'The audit of Foxworth Enterprises for December 31, 2025 is nearly complete. The engagement team at Baxter & Crane dates the representation letter March 15, 2026, matching the auditor''s report date. Under AU-C 580, regarding subsequent events management should represent that:', '["No events of any kind occurred between the balance sheet date and the report date", "The auditor is solely responsible for identifying and evaluating all subsequent events", "Only subsequent events involving cash transactions after year-end have been disclosed", "All events occurring subsequent to the balance sheet date that require adjustment or disclosure have been properly addressed in the financial statements"]'::jsonb, 3, 'AU-C 580.11 requires management to represent that all events subsequent to the balance sheet date requiring adjustment or disclosure under the applicable financial reporting framework have been properly treated in the financial statements. Choice A is unrealistic because events always occur after year-end; the issue is whether they require financial statement treatment. This complements the auditor''s own subsequent events procedures under AU-C 560.', 'medium', 2),

-- Q22: medium / L3 — Management's specialist use representation
(1, 'Written Representations', 'Cascade Properties engages an independent appraiser to value its $12 million real estate portfolio for December 31, 2025. The engagement team at Thornton & Marsh considers what representation to request about the specialist''s work. Under AU-C 500 and AU-C 580, the auditor should request management to represent that:', '["The auditor is fully responsible for evaluating the appraiser''s methodology and credentials", "The methods and significant assumptions used by management''s specialist are appropriate and the data provided to the specialist was complete and accurate", "The specialist''s valuation will not differ from actual sale prices by more than five percent", "The specialist''s credentials were verified by a government licensing authority prior to the engagement"]'::jsonb, 1, 'When management uses a specialist, AU-C 500.08 and AU-C 580.A13 support requesting representations that the specialist''s methods and significant assumptions are appropriate and that the data provided was complete and accurate. Management retains responsibility for the estimate even when using a specialist. Choice C imposes an unreasonable precision guarantee that no appraiser can reasonably provide.', 'medium', 3),

-- Q23: medium / L3 — Undisclosed side agreements representation
(1, 'Written Representations', 'During the audit of Northgate Logistics for December 31, 2025, the engagement team at Sullivan & York discovers that several vendor contracts contain nonstandard payment terms. The team requests a representation about undisclosed arrangements. Under AU-C 580, this representation should confirm that:', '["All vendor contracts were negotiated at arm''s length without any executive involvement", "The entity''s legal department reviewed and formally approved every vendor agreement", "There are no side agreements, whether oral or written, that modify the terms of disclosed arrangements and have not been communicated to the auditor", "All vendor contracts have been renegotiated within the preceding twelve months"]'::jsonb, 2, 'AU-C 580.A13 supports requesting additional representations when engagement circumstances warrant. A representation about the absence of undisclosed side agreements addresses the completeness and accuracy assertions for contractual obligations. Choice A is irrelevant to disclosure completeness, and choice B addresses internal approval processes rather than whether all arrangement terms have been fully communicated to the auditor.', 'medium', 3),

-- Q24: medium / L2 — Segment information representation
(1, 'Written Representations', 'Grandview Enterprises operates in three reportable segments and presents segment disclosures in its December 31, 2025 financial statements. The engagement team at Ashford & Miles drafts the management representation letter. Under AU-C 580, the auditor may request management to represent that:', '["The methods of measurement and presentation of reported segment information comply with the applicable financial reporting framework", "The entity intends to consolidate all operating segments into a single reporting unit next year", "Each segment''s revenue exceeds the ten percent quantitative threshold required by GAAP", "The auditor independently verified the cost allocation methodology applied to each segment"]'::jsonb, 0, 'AU-C 580.A13 supports requesting representations about whether segment identification, measurement methods, and disclosures comply with the applicable framework (ASC 280). Choice C states a quantitative threshold but does not confirm the overall appropriateness of measurement and presentation methods. The representation ensures management takes responsibility for segment reporting methodology and disclosure completeness.', 'medium', 2),

-- Q25: hard / L4 — Contradictory evidence after obtaining written representations
(1, 'Written Representations', 'During the audit of Lakeview Manufacturing for December 31, 2025, the engagement team at Crawford & Dunn obtains a representation letter in which management asserts no related-party transactions occurred during the year. One week later, the team discovers purchase orders totaling $1.2 million between Lakeview and an entity owned by its CEO''s spouse. Under AU-C 580, the auditor should:', '["Accept the signed representation as sufficient and issue an unmodified opinion", "Reconsider the reliability of management''s representations overall and evaluate the implications for other aspects of the audit", "Require management to revoke the original letter and issue a replacement excluding the related-party assertion", "Automatically withdraw from the engagement because management provided a false representation"]'::jsonb, 1, 'AU-C 580.17 requires the auditor to reconsider the reliability of all representations when contradictory evidence is discovered. The auditor must evaluate whether the inconsistency was intentional, whether it indicates broader unreliability, and its implications for other audit areas. Choice A ignores the contradictory evidence entirely. Unlike automatic withdrawal (choice D), the auditor first evaluates the nature and significance of the discrepancy.', 'hard', 4),

-- Q26: easy / L1 — Representations required by other AU-C sections
(1, 'Written Representations', 'Under AU-C 580, what is the relationship between written representations required by AU-C 580 and those required by other AU-C sections?', '["Other AU-C sections cannot require additional written representations beyond those in AU-C 580", "Written representations from other AU-C sections are obtained in separate letters from different management members", "Representations required by other AU-C sections replace those in AU-C 580 when both address the same topic", "Other AU-C sections may also require written representations, which are typically included in the same representation letter"]'::jsonb, 3, 'AU-C 580.06 acknowledges that other AU-C sections may require additional written representations on specific topics, such as AU-C 550 for related parties and AU-C 560 for subsequent events. These representations are typically consolidated into a single letter rather than obtained in separate documents (choice B). Choice A incorrectly states that only AU-C 580 can require representations from management.', 'easy', 1),

-- Q27: medium / L3 — Representation about financial reporting framework
(1, 'Written Representations', 'Trenton Supply Co. prepares its December 31, 2025 financial statements using a special purpose framework (tax basis). The engagement team at Morrison & Pratt drafts the management representation letter. Under AU-C 580, what representation should the auditor request regarding the financial reporting framework?', '["That the financial statements are prepared in accordance with the applicable financial reporting framework and that management considers the framework acceptable", "That the entity plans to transition from the tax basis to GAAP within the next fiscal year", "That the auditor selected the tax basis framework as the most appropriate for the entity", "That all financial statement users have unanimously approved the use of the tax basis framework"]'::jsonb, 0, 'AU-C 580.10-.11 requires management to acknowledge responsibility for preparing the financial statements in accordance with the applicable financial reporting framework. When a special purpose framework is used, the representation confirms that management selected the framework and considers it acceptable for its purposes. Choice C incorrectly attributes framework selection to the auditor, whereas this decision belongs to management.', 'medium', 3),

-- Q28: medium / L3 — Written representations in review engagements
(1, 'Written Representations', 'The engagement partner at Whitman & Cole performs a review engagement for Birchwood Retail''s December 31, 2025 financial statements under AR-C 90. The partner considers whether a management representation letter is required for this type of engagement. Under AR-C 90, written representations in a review engagement:', '["Are optional and obtained only when the accountant identifies specific risks during the review", "Are required only for review engagements of publicly traded entities", "Are required and should include management''s acknowledgment of its responsibility for the financial statements and the completeness of information provided", "Are replaced by oral inquiry of management during the final stage of the review"]'::jsonb, 2, 'AR-C 90.39 requires the accountant to obtain written representations from management in a review engagement, including management''s responsibility for the financial statements and completeness of information provided. Choice A is incorrect because representations are mandatory in all reviews, not discretionary. Although the review provides only limited assurance, the requirement for a written representation letter parallels the audit requirement under AU-C 580.', 'medium', 3),

-- Q29: easy / L1 — Written representations as necessary but not sufficient evidence
(1, 'Written Representations', 'Under AU-C 580, are management''s written representations considered sufficient audit evidence on their own for financial statement assertions?', '["No, they are required only for high-risk assertions and are sufficient for low-risk ones", "Yes, written representations provide the highest level of assurance available to the auditor", "No, they must always be accompanied by at least two independent external confirmations per assertion", "No, written representations provide necessary but not sufficient evidence and must be supplemented with other audit procedures"]'::jsonb, 3, 'AU-C 580.04 states that written representations alone do not provide sufficient appropriate audit evidence about any of the matters with which they deal. They are necessary evidence that must be corroborated with other audit procedures. Choice B incorrectly ranks representations as the highest assurance level, whereas external evidence obtained directly by the auditor is generally considered more reliable in the evidence hierarchy.', 'easy', 1),

-- Q30: hard / L3 — Implications when management cannot provide a representation
(1, 'Written Representations', 'During the audit of Hearthstone Energy for December 31, 2025, the engagement partner at Radcliffe & Stone requests a representation about the completeness of environmental remediation liabilities. The CFO states that management lacks sufficient knowledge to evaluate the completeness of these liabilities because an environmental assessment is still pending. Under AU-C 580, the auditor should:', '["Evaluate whether management''s inability to provide the representation constitutes a scope limitation and consider the effect on the auditor''s report", "Accept the CFO''s oral explanation and omit the environmental representation from the letter entirely", "Require management to hire an environmental specialist before signing any version of the representation letter", "Issue an unmodified opinion because the pending assessment is outside management''s direct control"]'::jsonb, 0, 'AU-C 580.19 requires the auditor to evaluate the implications when management is unable to provide requested representations. If management cannot represent the completeness of a significant liability, this may constitute a scope limitation affecting the audit report. Choice D is incorrect because management''s inability to represent a significant assertion raises doubt about whether sufficient appropriate evidence exists, regardless of the underlying reason.', 'hard', 3)
;

COMMIT;
